import json

def flatten(obj):
    """Flatten nested dicts with '.'; empty dicts contribute no keys."""
    flat = {}
    def rec(prefix, value):
        for k, v in value.items():
            key = f"{prefix}.{k}" if prefix else k
            if isinstance(v, dict):
                rec(key, v)
            else:
                flat[key] = v
    rec("", obj)
    return flat

def cell(value):
    if value is None:
        return ""
    if isinstance(value, bool):
        return "true" if value else "false"
    if isinstance(value, (int, float)):
        return json.dumps(value, ensure_ascii=False)
    if isinstance(value, str):
        return value
    if isinstance(value, list):
        return json.dumps(value, ensure_ascii=False, separators=(",", ":"))
    return str(value)  # unreachable for JSON-derived values

def quote(field):
    if any(c in field for c in (",", '"', "\n")):
        return '"' + field.replace('"', '""') + '"'
    return field

rows = []      # list of flattened dicts
all_keys = set()
errors = []

with open("/data/events.jsonl", "r", encoding="utf-8") as f:
    for n, line in enumerate(f, start=1):
        stripped = line.strip()
        if not stripped:
            continue  # blank/whitespace-only: skip silently
        try:
            value = json.loads(stripped)
        except (json.JSONDecodeError, ValueError):
            errors.append(n)
            continue
        if not isinstance(value, dict):
            errors.append(n)
            continue
        flat = flatten(value)
        rows.append(flat)
        all_keys.update(flat.keys())

columns = sorted(all_keys)

out_lines = [",".join(quote(c) for c in columns)]
for flat in rows:
    out_lines.append(",".join(quote(cell(flat.get(c))) for c in columns))

with open("/out/events.csv", "w", encoding="utf-8", newline="") as f:
    f.write("\n".join(out_lines) + "\n")

with open("/out/errors.txt", "w", encoding="utf-8", newline="") as f:
    for n in errors:
        f.write(f"line {n}\n")
EOF
